CREATE INDEX "Availability_profileId_startsAt_endsAt_idx" ON "Availability"("profileId", "startsAt", "endsAt");
CREATE UNIQUE INDEX "OrderCollaborator_orderId_userId_role_key" ON "OrderCollaborator"("orderId", "userId", "role");
CREATE INDEX "OrderCollaborator_userId_idx" ON "OrderCollaborator"("userId");
CREATE INDEX "MediaAsset_deliveryId_createdAt_idx" ON "MediaAsset"("deliveryId", "createdAt");
CREATE INDEX "TimecodeComment_deliveryId_timecodeMs_idx" ON "TimecodeComment"("deliveryId", "timecodeMs");
CREATE UNIQUE INDEX "PaymentIntent_subOrderId_key" ON "PaymentIntent"("subOrderId");
CREATE UNIQUE INDEX "PaymentIntent_providerRef_key" ON "PaymentIntent"("providerRef");
